-- Identity schema for the Policy & HR Copilot (PostgreSQL 14+)
-- GENERATED FILE: edit the generator (backend/app/db/sqlgen.py), then run
--   python -m app.db.manage export-sql
-- Creates the `auth` schema (roles, permissions, users, refresh tokens, audit log) and stamps Alembic at
-- revision 0001, so the application's startup migration is then a no-op.
-- Fails if the tables already exist: run drop_schema.sql first to start over.
-- Usage: psql -U policy -d policy_copilot -f db/schema.sql

BEGIN;

CREATE SCHEMA IF NOT EXISTS auth;

CREATE TABLE auth.alembic_version (
    version_num VARCHAR(32) NOT NULL, 
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Migration 0001: auth schema

CREATE SCHEMA IF NOT EXISTS auth;

CREATE TABLE auth.roles (
    id SERIAL NOT NULL, 
    name VARCHAR(32) NOT NULL, 
    level INTEGER NOT NULL, 
    description VARCHAR(200) DEFAULT '' NOT NULL, 
    CONSTRAINT pk_roles PRIMARY KEY (id), 
    CONSTRAINT uq_roles_name UNIQUE (name)
);

CREATE TABLE auth.permissions (
    id SERIAL NOT NULL, 
    code VARCHAR(64) NOT NULL, 
    description VARCHAR(200) DEFAULT '' NOT NULL, 
    CONSTRAINT pk_permissions PRIMARY KEY (id), 
    CONSTRAINT uq_permissions_code UNIQUE (code)
);

CREATE TABLE auth.role_permissions (
    role_id INTEGER NOT NULL, 
    permission_id INTEGER NOT NULL, 
    CONSTRAINT pk_role_permissions PRIMARY KEY (role_id, permission_id), 
    CONSTRAINT fk_role_permissions_role_id_roles FOREIGN KEY(role_id) REFERENCES auth.roles (id) ON DELETE CASCADE, 
    CONSTRAINT fk_role_permissions_permission_id_permissions FOREIGN KEY(permission_id) REFERENCES auth.permissions (id) ON DELETE CASCADE
);

CREATE TABLE auth.users (
    id UUID NOT NULL, 
    username VARCHAR(64) NOT NULL, 
    email VARCHAR(255), 
    full_name VARCHAR(120) NOT NULL, 
    password_hash VARCHAR(255) NOT NULL, 
    role_id INTEGER NOT NULL, 
    department VARCHAR(80) DEFAULT 'General' NOT NULL, 
    manager_id UUID, 
    is_active BOOLEAN DEFAULT true NOT NULL, 
    failed_login_attempts INTEGER DEFAULT '0' NOT NULL, 
    locked_until TIMESTAMP WITH TIME ZONE, 
    last_login_at TIMESTAMP WITH TIME ZONE, 
    password_changed_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_users PRIMARY KEY (id), 
    CONSTRAINT uq_users_username UNIQUE (username), 
    CONSTRAINT uq_users_email UNIQUE (email), 
    CONSTRAINT ck_users_username_lowercase CHECK (username = lower(username)), 
    CONSTRAINT fk_users_role_id_roles FOREIGN KEY(role_id) REFERENCES auth.roles (id), 
    CONSTRAINT fk_users_manager_id_users FOREIGN KEY(manager_id) REFERENCES auth.users (id) ON DELETE SET NULL
);

CREATE INDEX ix_users_role_id ON auth.users (role_id);

CREATE INDEX ix_users_manager_id ON auth.users (manager_id);

CREATE TABLE auth.refresh_tokens (
    id UUID NOT NULL, 
    user_id UUID NOT NULL, 
    token_hash VARCHAR(64) NOT NULL, 
    family_id UUID NOT NULL, 
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    revoked_at TIMESTAMP WITH TIME ZONE, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    ip_address VARCHAR(64), 
    user_agent VARCHAR(255), 
    CONSTRAINT pk_refresh_tokens PRIMARY KEY (id), 
    CONSTRAINT uq_refresh_tokens_token_hash UNIQUE (token_hash), 
    CONSTRAINT fk_refresh_tokens_user_id_users FOREIGN KEY(user_id) REFERENCES auth.users (id) ON DELETE CASCADE
);

CREATE INDEX ix_refresh_tokens_user_id ON auth.refresh_tokens (user_id);

CREATE INDEX ix_refresh_tokens_family_id ON auth.refresh_tokens (family_id);

CREATE TABLE auth.audit_log (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY, 
    user_id UUID, 
    username VARCHAR(64), 
    action VARCHAR(64) NOT NULL, 
    success BOOLEAN NOT NULL, 
    ip_address VARCHAR(64), 
    detail JSONB, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_audit_log PRIMARY KEY (id), 
    CONSTRAINT fk_audit_log_user_id_users FOREIGN KEY(user_id) REFERENCES auth.users (id) ON DELETE SET NULL
);

CREATE INDEX ix_audit_log_created_at ON auth.audit_log (created_at);

CREATE INDEX ix_audit_log_user_id ON auth.audit_log (user_id);

INSERT INTO auth.alembic_version (version_num) VALUES ('0001');

COMMIT;
